// generated by timing.js: do not edit
(function () { const TL = {"DURATION":422.65,"lines":[{"at":1.2,"dur":1.36,"text":"You look up from the beach.","who":"narrator","scene":"beach"},{"at":2.82,"dur":1.75,"text":"A plane crosses the sky.","who":"narrator","scene":"beach"},{"at":4.83,"dur":1.87,"text":"You can read the name on its tail.","who":"narrator","scene":"beach"},{"at":6.96,"dur":1.36,"text":"And the pilot's face...","who":"narrator","scene":"beach"},{"at":8.87,"dur":0.69,"text":"waving.","who":"narrator","scene":"beach"},{"at":10.72,"dur":1.34,"text":"You glance at the Moon.","who":"narrator","scene":"moon"},{"at":12.32,"dur":1.84,"text":"Craters. Mountains. Shadows.","who":"narrator","scene":"moon"},{"at":14.42,"dur":1.1,"text":"No telescope.","who":"narrator","scene":"moon"},{"at":16.68,"dur":2.85,"text":"A friend points at a hill two kilometers away.","who":"narrator","scene":"hill"},{"at":19.99,"dur":0.88,"text":"What's that?","who":"friend","scene":"hill"},{"at":21.49,"dur":0.89,"text":"You squint.","who":"narrator","scene":"hill"},{"at":22.64,"dur":0.67,"text":"A man.","who":"narrator","scene":"hill"},{"at":23.57,"dur":1.18,"text":"Eating a sandwich.","who":"narrator","scene":"hill"},{"at":25.01,"dur":0.63,"text":"Ham...","who":"narrator","scene":"hill"},{"at":26.19,"dur":1.28,"text":"and too much mustard.","who":"narrator","scene":"hill"},{"at":28.63,"dur":1.24,"text":"Your name is Theo.","who":"narrator","scene":"plate"},{"at":30.13,"dur":3.15,"text":"A British driving test asks you to read a number plate...","who":"narrator","scene":"plate"},{"at":33.83,"dur":1.27,"text":"from twenty meters.","who":"narrator","scene":"plate"},{"at":35.36,"dur":0.55,"text":"You?","who":"narrator","scene":"plate"},{"at":36.33,"dur":1.08,"text":"Two kilometers.","who":"narrator","scene":"plate"},{"at":38.57,"dur":4.65,"text":"Normal eyes pick out details about one sixtieth of a degree wide.","who":"narrator","scene":"acuity"},{"at":43.48,"dur":0.74,"text":"Yours?","who":"narrator","scene":"acuity"},{"at":44.64,"dur":1.52,"text":"A hundred times finer.","who":"narrator","scene":"acuity"},{"at":47.32,"dur":1.18,"text":"But here's the rule.","who":"narrator","scene":"rule"},{"at":48.76,"dur":2.3,"text":"Your eyes got a hundred times sharper.","who":"narrator","scene":"rule"},{"at":51.32,"dur":1.24,"text":"Your legs did not.","who":"narrator","scene":"rule"},{"at":52.82,"dur":2.5,"text":"You can spot trouble two kilometers away.","who":"narrator","scene":"rule"},{"at":55.58,"dur":1.19,"text":"You still reach it...","who":"narrator","scene":"rule"},{"at":57.32,"dur":1.17,"text":"at human speed.","who":"narrator","scene":"rule"},{"at":59.65,"dur":3,"text":"So what if your eyesight was a hundred times sharper?","who":"narrator","scene":"title"},{"at":63.97,"dur":1.86,"text":"Plus: you never need glasses.","who":"narrator","scene":"class"},{"at":66.09,"dur":3.63,"text":"From the back row, you can read the teacher's notes on her desk.","who":"narrator","scene":"class"},{"at":69.98,"dur":0.73,"text":"Do you?","who":"narrator","scene":"class"},{"at":71.13,"dur":0.62,"text":"Never.","who":"narrator","scene":"class"},{"at":72.01,"dur":0.78,"text":"Mostly.","who":"narrator","scene":"class"},{"at":73.05,"dur":2.55,"text":"Minus: you can read everything else too.","who":"narrator","scene":"class"},{"at":75.86,"dur":1.52,"text":"Every pore on her nose.","who":"narrator","scene":"class"},{"at":77.64,"dur":1.13,"text":"Every grey hair...","who":"narrator","scene":"class"},{"at":79.32,"dur":1.66,"text":"she thinks nobody can see.","who":"narrator","scene":"class"},{"at":81.44,"dur":2.32,"text":"Okay, class. Why is Theo staring at me?","who":"teacher","scene":"class"},{"at":85.08,"dur":3.73,"text":"At the football match, you sit in the cheapest seat in the stadium.","who":"narrator","scene":"stadium"},{"at":89.07,"dur":2.37,"text":"You can still read the stitching on the ball.","who":"narrator","scene":"stadium"},{"at":92.6,"dur":3.47,"text":"In birdwatching club, everyone shares binoculars.","who":"narrator","scene":"birds"},{"at":96.33,"dur":1.25,"text":"You count the feathers...","who":"narrator","scene":"birds"},{"at":98.13,"dur":0.83,"text":"out loud.","who":"narrator","scene":"birds"},{"at":100.12,"dur":0.76,"text":"The catch?","who":"narrator","scene":"fovea"},{"at":101.3,"dur":3.5,"text":"Your sharpest vision only lives in one tiny spot.","who":"narrator","scene":"fovea"},{"at":105.06,"dur":2.08,"text":"Hold your thumb out at arm's length.","who":"narrator","scene":"fovea"},{"at":107.4,"dur":1.14,"text":"That tiny patch?","who":"narrator","scene":"fovea"},{"at":108.96,"dur":2.38,"text":"That's all your eyes see sharply at once.","who":"narrator","scene":"fovea"},{"at":111.6,"dur":1.25,"text":"So your eyes jump.","who":"narrator","scene":"fovea"},{"at":113.11,"dur":1.68,"text":"Three or four times a second.","who":"narrator","scene":"fovea"},{"at":115.05,"dur":1.1,"text":"Building the rest.","who":"narrator","scene":"fovea"},{"at":116.41,"dur":4.48,"text":"Except now, every jump brings in ten thousand times more detail.","who":"narrator","scene":"fovea"},{"at":121.15,"dur":1.05,"text":"And your brain...","who":"narrator","scene":"fovea"},{"at":122.75,"dur":1.35,"text":"has to sort all of it.","who":"narrator","scene":"fovea"},{"at":124.36,"dur":0.72,"text":"Headaches.","who":"narrator","scene":"fovea"},{"at":125.34,"dur":1.18,"text":"Every single day.","who":"narrator","scene":"fovea"},{"at":127.68,"dur":1.8,"text":"But where it gets really crazy...","who":"narrator","scene":"harbor"},{"at":130.03,"dur":0.96,"text":"is the video.","who":"narrator","scene":"harbor"},{"at":131.25,"dur":1.92,"text":"A tourist films you at the harbor.","who":"narrator","scene":"harbor"},{"at":133.43,"dur":3.09,"text":"You read a tiny warning sign on a ship far out at sea.","who":"narrator","scene":"harbor"},{"at":136.78,"dur":1.41,"text":"The clip goes everywhere.","who":"narrator","scene":"harbor"},{"at":139.35,"dur":1.5,"text":"By Friday, a message.","who":"narrator","scene":"message"},{"at":141.11,"dur":0.98,"text":"Mr. Black.","who":"narrator","scene":"message"},{"at":142.35,"dur":0.68,"text":"Polite.","who":"narrator","scene":"message"},{"at":143.29,"dur":0.64,"text":"Rich.","who":"narrator","scene":"message"},{"at":144.39,"dur":0.89,"text":"I have a job.","who":"black","scene":"message"},{"at":145.54,"dur":3.27,"text":"Sit in a café. Read a few phones. A few bank cards.","who":"black","scene":"message"},{"at":149.07,"dur":1.17,"text":"Nobody gets hurt.","who":"black","scene":"message"},{"at":150.5,"dur":1.23,"text":"Doesn't that sound easy?","who":"black","scene":"message"},{"at":153.05,"dur":1.13,"text":"And there's a cost.","who":"narrator","scene":"cost"},{"at":154.44,"dur":1.3,"text":"You can't switch it off.","who":"narrator","scene":"cost"},{"at":156,"dur":0.94,"text":"Peeling paint.","who":"narrator","scene":"cost"},{"at":157.2,"dur":1.21,"text":"Cracks in bridges.","who":"narrator","scene":"cost"},{"at":158.67,"dur":2.64,"text":"Mold in the bread before anyone else can see it.","who":"narrator","scene":"cost"},{"at":161.57,"dur":1.43,"text":"Your eyes never rest.","who":"narrator","scene":"cost"},{"at":163.26,"dur":1.99,"text":"And the world stops looking beautiful.","who":"narrator","scene":"cost"},{"at":165.51,"dur":1.02,"text":"It just looks...","who":"narrator","scene":"cost"},{"at":167.08,"dur":0.86,"text":"detailed.","who":"narrator","scene":"cost"},{"at":168.2,"dur":1.54,"text":"Sunsets turn into dust.","who":"narrator","scene":"cost"},{"at":170,"dur":1.59,"text":"Faces turn into maps.","who":"narrator","scene":"cost"},{"at":172.75,"dur":1.55,"text":"Then there's Grandpa Sam.","who":"narrator","scene":"grandpa"},{"at":174.56,"dur":2.47,"text":"He used to be a lifeguard on this beach.","who":"narrator","scene":"grandpa"},{"at":177.29,"dur":2.24,"text":"Now he has macular degeneration.","who":"narrator","scene":"grandpa"},{"at":179.79,"dur":1.43,"text":"It's a real disease.","who":"narrator","scene":"grandpa"},{"at":181.48,"dur":3.99,"text":"It slowly wipes out the center of your vision, while the edges stay.","who":"narrator","scene":"grandpa"},{"at":185.73,"dur":1.21,"text":"So you see the most.","who":"narrator","scene":"grandpa"},{"at":187.2,"dur":1.25,"text":"And he sees the least.","who":"narrator","scene":"grandpa"},{"at":189.61,"dur":2.43,"text":"Every Sunday, you climb the cliff together.","who":"narrator","scene":"cliff"},{"at":192.3,"dur":1.75,"text":"He flies his big red kite.","who":"narrator","scene":"cliff"},{"at":194.31,"dur":1.97,"text":"It's the one thing he still finds...","who":"narrator","scene":"cliff"},{"at":196.83,"dur":1.56,"text":"from the corner of his eye.","who":"narrator","scene":"cliff"},{"at":198.85,"dur":2.68,"text":"I can't see the gulls anymore, Theo.","who":"grandpa","scene":"cliff"},{"at":201.79,"dur":1.4,"text":"So you tell me.","who":"grandpa","scene":"cliff"},{"at":203.65,"dur":0.88,"text":"And you do.","who":"narrator","scene":"cliff"},{"at":204.79,"dur":0.84,"text":"Every wing.","who":"narrator","scene":"cliff"},{"at":205.89,"dur":0.97,"text":"Every wave.","who":"narrator","scene":"cliff"},{"at":207.12,"dur":1.37,"text":"You make a promise too.","who":"narrator","scene":"cliff"},{"at":208.95,"dur":0.96,"text":"If I can see it...","who":"theo","scene":"cliff"},{"at":210.46,"dur":1,"text":"it's mine to fix.","who":"theo","scene":"cliff"},{"at":212.62,"dur":1.01,"text":"Sunday comes.","who":"narrator","scene":"roof"},{"at":213.89,"dur":1.46,"text":"But you're not on the cliff.","who":"narrator","scene":"roof"},{"at":215.61,"dur":3.36,"text":"You're on a café roof, two kilometers down the coast.","who":"narrator","scene":"roof"},{"at":219.23,"dur":1.44,"text":"Mr. Black's job.","who":"narrator","scene":"roof"},{"at":220.93,"dur":2.33,"text":"Below you, a woman at a cash machine.","who":"narrator","scene":"roof"},{"at":223.52,"dur":0.83,"text":"Her card.","who":"narrator","scene":"roof"},{"at":224.61,"dur":0.89,"text":"Her keys.","who":"narrator","scene":"roof"},{"at":225.76,"dur":0.76,"text":"Her PIN.","who":"narrator","scene":"roof"},{"at":226.78,"dur":2.04,"text":"Mr. Black's voice in your ear.","who":"narrator","scene":"roof"},{"at":229.28,"dur":1,"text":"Four numbers, kid.","who":"black","scene":"roof"},{"at":230.54,"dur":0.84,"text":"Then you're done.","who":"black","scene":"roof"},{"at":232.54,"dur":0.6,"text":"Then...","who":"narrator","scene":"sea"},{"at":233.69,"dur":0.84,"text":"you see it.","who":"narrator","scene":"sea"},{"at":234.79,"dur":1.53,"text":"Far out past the beach.","who":"narrator","scene":"sea"},{"at":236.58,"dur":1.01,"text":"A small boy.","who":"narrator","scene":"sea"},{"at":237.85,"dur":1.4,"text":"On an orange board.","who":"narrator","scene":"sea"},{"at":239.51,"dur":0.83,"text":"Drifting...","who":"narrator","scene":"sea"},{"at":240.89,"dur":0.68,"text":"fast.","who":"narrator","scene":"sea"},{"at":241.83,"dur":1.87,"text":"The water around him is darker.","who":"narrator","scene":"sea"},{"at":243.96,"dur":0.68,"text":"Flatter.","who":"narrator","scene":"sea"},{"at":244.9,"dur":0.99,"text":"A rip current.","who":"narrator","scene":"sea"},{"at":246.15,"dur":2.63,"text":"Some rips move faster than an Olympic swimmer.","who":"narrator","scene":"sea"},{"at":249.04,"dur":1.9,"text":"Has anyone on the sand noticed?","who":"narrator","scene":"sea"},{"at":251.36,"dur":0.59,"text":"No.","who":"narrator","scene":"sea"},{"at":252.21,"dur":2.15,"text":"The lifeguard is looking the wrong way.","who":"narrator","scene":"sea"},{"at":254.62,"dur":1.08,"text":"Two kilometers.","who":"narrator","scene":"sea"},{"at":255.96,"dur":2.46,"text":"Even sprinting, you'd need six minutes.","who":"narrator","scene":"sea"},{"at":258.68,"dur":0.94,"text":"Maybe more.","who":"narrator","scene":"sea"},{"at":259.88,"dur":1.82,"text":"The board slips from his arms.","who":"narrator","scene":"sea"},{"at":262.86,"dur":0.54,"text":"Theo?","who":"black","scene":"choice"},{"at":263.82,"dur":1.01,"text":"The numbers. Now.","who":"black","scene":"choice"},{"at":265.29,"dur":1.47,"text":"You can see the PIN.","who":"narrator","scene":"choice"},{"at":267.02,"dur":1.2,"text":"You can see the boy.","who":"narrator","scene":"choice"},{"at":268.48,"dur":1.21,"text":"You can't have both.","who":"narrator","scene":"choice"},{"at":269.95,"dur":0.74,"text":"The money...","who":"narrator","scene":"choice"},{"at":271.24,"dur":0.86,"text":"or the boy.","who":"narrator","scene":"choice"},{"at":273.26,"dur":1.31,"text":"You drop the earpiece.","who":"narrator","scene":"call"},{"at":275.03,"dur":0.96,"text":"If I can see it...","who":"theo","scene":"call"},{"at":276.54,"dur":1,"text":"it's mine to fix.","who":"theo","scene":"call"},{"at":278,"dur":2.67,"text":"You call the one person on that beach you trust.","who":"narrator","scene":"call"},{"at":281.13,"dur":1.29,"text":"Grandpa. Kite. Up. Now.","who":"theo","scene":"call"},{"at":282.88,"dur":1.26,"text":"He doesn't ask why.","who":"narrator","scene":"call"},{"at":285.3,"dur":1.39,"text":"The red kite climbs.","who":"narrator","scene":"kite"},{"at":287.15,"dur":1.13,"text":"Left, Grandpa. More.","who":"theo","scene":"kite"},{"at":288.54,"dur":1.02,"text":"Stop. Hold it there.","who":"theo","scene":"kite"},{"at":290.02,"dur":1.65,"text":"Grandpa can't see the boy.","who":"narrator","scene":"kite"},{"at":291.93,"dur":1.36,"text":"But he can see his kite.","who":"narrator","scene":"kite"},{"at":293.55,"dur":2.6,"text":"And now it hangs right above that tiny head.","who":"narrator","scene":"kite"},{"at":297.31,"dur":1.83,"text":"You call the lifeguard station.","who":"narrator","scene":"nova"},{"at":299.4,"dur":1.32,"text":"Her name is Nova.","who":"narrator","scene":"nova"},{"at":301.18,"dur":1.06,"text":"Follow the red kite.","who":"theo","scene":"nova"},{"at":302.5,"dur":0.93,"text":"He's right under it.","who":"theo","scene":"nova"},{"at":303.89,"dur":1.96,"text":"Nova grabs the rescue board.","who":"narrator","scene":"nova"},{"at":306.11,"dur":1.53,"text":"She doesn't fight the current.","who":"narrator","scene":"nova"},{"at":307.9,"dur":1.17,"text":"She rides it out...","who":"narrator","scene":"nova"},{"at":309.62,"dur":1.32,"text":"then cuts sideways.","who":"narrator","scene":"nova"},{"at":311.2,"dur":1.42,"text":"And that's the real lesson.","who":"narrator","scene":"nova"},{"at":312.88,"dur":2.28,"text":"If a rip ever pulls you out, don't fight it.","who":"narrator","scene":"nova"},{"at":315.42,"dur":1.71,"text":"Swim parallel to the shore.","who":"narrator","scene":"nova"},{"at":317.39,"dur":1.2,"text":"Then come back in.","who":"narrator","scene":"nova"},{"at":319.75,"dur":3.17,"text":"Three minutes later, the boy is coughing on the sand.","who":"narrator","scene":"saved"},{"at":323.18,"dur":0.81,"text":"Alive...","who":"narrator","scene":"saved"},{"at":324.54,"dur":1.88,"text":"and furious about his board.","who":"narrator","scene":"saved"},{"at":326.68,"dur":2.94,"text":"The whole beach is cheering for an old man with a kite.","who":"narrator","scene":"saved"},{"at":330.78,"dur":1.18,"text":"And Mr. Black?","who":"narrator","scene":"police"},{"at":332.38,"dur":1.92,"text":"You never gave him a single number.","who":"narrator","scene":"police"},{"at":334.56,"dur":1.81,"text":"You gave the police something better.","who":"narrator","scene":"police"},{"at":336.63,"dur":0.88,"text":"His car.","who":"narrator","scene":"police"},{"at":337.77,"dur":0.85,"text":"His plate.","who":"narrator","scene":"police"},{"at":338.88,"dur":0.85,"text":"His face.","who":"narrator","scene":"police"},{"at":339.99,"dur":0.91,"text":"All read...","who":"narrator","scene":"police"},{"at":341.45,"dur":1.63,"text":"from two kilometers away.","who":"narrator","scene":"police"},{"at":343.34,"dur":1.85,"text":"Cover your PIN, by the way.","who":"narrator","scene":"police"},{"at":345.45,"dur":1.66,"text":"You never know who's watching.","who":"narrator","scene":"police"},{"at":348.27,"dur":1.95,"text":"That evening, you're back on the cliff.","who":"narrator","scene":"sunset"},{"at":350.48,"dur":1.67,"text":"Grandpa grips your shoulder.","who":"narrator","scene":"sunset"},{"at":352.61,"dur":1.52,"text":"Tell me what you see.","who":"grandpa","scene":"sunset"},{"at":354.59,"dur":3.48,"text":"For the first time in weeks, the world isn't just detail.","who":"narrator","scene":"sunset"},{"at":358.33,"dur":1.13,"text":"It's gold water.","who":"narrator","scene":"sunset"},{"at":359.72,"dur":0.94,"text":"A red kite.","who":"narrator","scene":"sunset"},{"at":360.92,"dur":1.94,"text":"And a family hugging a little boy.","who":"narrator","scene":"sunset"},{"at":363.12,"dur":0.82,"text":"Beautiful.","who":"narrator","scene":"sunset"},{"at":365.1,"dur":1.25,"text":"Is any of this real?","who":"narrator","scene":"real"},{"at":366.77,"dur":0.69,"text":"Partly.","who":"narrator","scene":"real"},{"at":367.72,"dur":4.63,"text":"Macular degeneration is real, and it steals central vision first.","who":"narrator","scene":"real"},{"at":372.61,"dur":1.67,"text":"Rip currents are real too.","who":"narrator","scene":"real"},{"at":374.54,"dur":1.9,"text":"But eyes a hundred times sharper?","who":"narrator","scene":"real"},{"at":376.86,"dur":1.12,"text":"Physics says no.","who":"narrator","scene":"real"},{"at":378.24,"dur":2.7,"text":"Light spreads out as it passes through your pupil.","who":"narrator","scene":"real"},{"at":381.2,"dur":2.77,"text":"A normal pupil is a few millimeters wide.","who":"narrator","scene":"real"},{"at":384.23,"dur":1.45,"text":"That's already near the limit.","who":"narrator","scene":"real"},{"at":385.94,"dur":1.55,"text":"A hundred times sharper?","who":"narrator","scene":"real"},{"at":387.91,"dur":2.61,"text":"You'd need pupils a hundred times wider.","who":"narrator","scene":"real"},{"at":390.78,"dur":1.79,"text":"Roughly thirty centimeters.","who":"narrator","scene":"real"},{"at":392.83,"dur":0.68,"text":"Eyes...","who":"narrator","scene":"real"},{"at":394.06,"dur":1.43,"text":"the size of pizzas.","who":"narrator","scene":"real"},{"at":395.75,"dur":3.22,"text":"Which, to be fair, would make birdwatching awkward.","who":"narrator","scene":"real"},{"at":400.13,"dur":1.81,"text":"That night, you look up at the Moon.","who":"narrator","scene":"sting"},{"at":402.2,"dur":1.57,"text":"And something on its surface...","who":"narrator","scene":"sting"},{"at":404.32,"dur":0.74,"text":"moves.","who":"narrator","scene":"sting"},{"at":406.22,"dur":3.18,"text":"So would you trade normal eyes for pizza-sized ones?","who":"narrator","scene":"cta"},{"at":409.82,"dur":0.95,"text":"What do you think?","who":"narrator","scene":"cta"},{"at":411.19,"dur":4.15,"text":"Tell us in the comments, and tell us which superpower we should do next.","who":"narrator","scene":"cta"},{"at":415.6,"dur":2.29,"text":"Hit like, and subscribe for Part Two.","who":"narrator","scene":"cta"}],"scenes":[{"id":"beach","t0":0,"t1":10.27},{"id":"moon","t0":10.27,"t1":16.23},{"id":"hill","t0":16.23,"t1":28.18},{"id":"plate","t0":28.18,"t1":38.12},{"id":"acuity","t0":38.12,"t1":46.87},{"id":"rule","t0":46.87,"t1":59.2},{"id":"title","t0":59.2,"t1":63.52},{"id":"class","t0":63.52,"t1":84.63},{"id":"stadium","t0":84.63,"t1":92.15},{"id":"birds","t0":92.15,"t1":99.67},{"id":"fovea","t0":99.67,"t1":127.23},{"id":"harbor","t0":127.23,"t1":138.9},{"id":"message","t0":138.9,"t1":152.6},{"id":"cost","t0":152.6,"t1":172.3},{"id":"grandpa","t0":172.3,"t1":189.16},{"id":"cliff","t0":189.16,"t1":212.17},{"id":"roof","t0":212.17,"t1":232.09},{"id":"sea","t0":232.09,"t1":262.41},{"id":"choice","t0":262.41,"t1":272.81},{"id":"call","t0":272.81,"t1":284.85},{"id":"kite","t0":284.85,"t1":296.86},{"id":"nova","t0":296.86,"t1":319.3},{"id":"saved","t0":319.3,"t1":330.33},{"id":"police","t0":330.33,"t1":347.82},{"id":"sunset","t0":347.82,"t1":364.65},{"id":"real","t0":364.65,"t1":399.68},{"id":"sting","t0":399.68,"t1":405.77},{"id":"cta","t0":405.77,"t1":422.65}]};
if (typeof module !== 'undefined') module.exports = TL; else globalThis.TIMELINE = TL; })();
